import * as React from 'react';

/**
 * The content `Static.FlowText` can split, and the slicing of it into a piece's text.
 *
 * A FlowText measures the text nodes its children render, in DOM order, and a plan cuts that text
 * at UTF-16 offsets. The React children map onto those text nodes one to one only while they are
 * strings, numbers and host elements that render nothing but their children: so the children are
 * text and inline text elements, and anything else (a block, a component, inner HTML) makes the
 * item unsplittable rather than cut somewhere the measurement never saw.
 */
export const FLOW_TEXT_INLINE_TAGS = new Set([
  'a', 'abbr', 'b', 'bdi', 'bdo', 'br', 'cite', 'code', 'data', 'del', 'dfn', 'em', 'i', 'ins',
  'kbd', 'mark', 's', 'samp', 'small', 'span', 'strong', 'sub', 'sup', 'time', 'u', 'var', 'wbr',
]);

const BREAK_TAGS = new Set(['br']);

function elementName(type) {
  if (typeof type === 'string') return type;
  if (typeof type === 'function') return type.displayName || type.name || 'Component';
  if (type && typeof type === 'object') return type.displayName || 'Component';
  return 'Component';
}

/**
 * The text the children render, the offsets of their `<br>` elements, and why they cannot be split
 * if they cannot: `{ reason: 'block-content' | 'component-content', name }`.
 */
export function inspectFlowTextContent(children) {
  let text = '';
  let problem = null;
  const breaks = [];
  const visit = (node) => {
    if (problem || node === null || node === undefined || typeof node === 'boolean') return;
    if (typeof node === 'string' || typeof node === 'number' || typeof node === 'bigint') {
      text += String(node);
      return;
    }
    if (Array.isArray(node)) {
      node.forEach(visit);
      return;
    }
    if (React.isValidElement(node)) {
      const props = node.props ?? {};
      if (node.type === React.Fragment) {
        visit(props.children);
        return;
      }
      if (typeof node.type === 'string') {
        if (!FLOW_TEXT_INLINE_TAGS.has(node.type) || props.dangerouslySetInnerHTML) {
          problem = { reason: 'block-content', name: node.type };
          return;
        }
        if (BREAK_TAGS.has(node.type)) breaks.push(text.length);
        visit(props.children);
        return;
      }
      problem = { reason: 'component-content', name: elementName(node.type) };
      return;
    }
    problem = { reason: 'component-content', name: typeof node };
  };
  visit(children);
  return { text, breaks, problem };
}

const isSpace = (character) => character === ' ' || character === '\n' || character === '\t' ||
  character === '\r' || character === '\f';
const SOFT_HYPHEN = '\u00ad';

/**
 * The children of the piece `[from, to)` of a FlowText's text: strings sliced, elements cloned with
 * their sliced children, elements without text in the piece dropped, a `<br>` at a piece boundary
 * dropped (the page break is the line break).
 *
 * A continuation piece starts after the whitespace its line break consumed (indentation after a
 * forced break stays). `hyphens` are the measured breaks that showed a hyphen (`hyphens: auto`, a
 * soft hyphen): inside the piece they become soft hyphens and `manualHyphens` is set, so the slice
 * breaks exactly where the measured text did (a truncated word would hyphenate differently); at
 * the piece's end the piece ends with a visible hyphen (a trailing soft hyphen becomes one). Any
 * other piece end drops its trailing whitespace.
 * `justifyLast`: the piece ends at a soft break, so a justified text justifies its last line too.
 */
export function sliceFlowTextContent(children, { text, breaks = [] }, { from, to, part, parts, hyphens = [] }) {
  const first = part === 0;
  const last = part === parts - 1;
  let start = first ? 0 : Math.max(0, from);
  let stop = last ? text.length : Math.min(text.length, to);
  const forcedBreakAt = (offset) => text[offset - 1] === '\n' || breaks.includes(offset);

  if (!first) {
    let index = start;
    while (index < stop && isSpace(text[index])) index += 1;
    const newline = text.slice(start, index).lastIndexOf('\n');
    if (newline >= 0) start += newline + 1;
    else if (!forcedBreakAt(start)) start = index;
  }

  let hyphen = false;
  let forcedEnd = false;
  if (!last) {
    if (hyphens.includes(stop) && !breaks.includes(stop)) {
      if (text[stop - 1] === SOFT_HYPHEN) stop -= 1;
      hyphen = true;
    } else {
      let index = stop;
      while (index > start && isSpace(text[index - 1])) index -= 1;
      if (breaks.includes(stop) || text.slice(index, stop).includes('\n')) forcedEnd = true;
      stop = index;
    }
  }
  const softHyphens = hyphens.filter((offset) => offset > start && offset < stop && text[offset - 1] !== SOFT_HYPHEN);

  let offset = 0;
  let hyphenPlaced = false;
  const slice = (node) => {
    if (node === null || node === undefined || typeof node === 'boolean') return null;
    if (typeof node === 'string' || typeof node === 'number' || typeof node === 'bigint') {
      const value = String(node);
      const nodeStart = offset;
      const nodeEnd = offset + value.length;
      offset = nodeEnd;
      const sliceStart = Math.max(nodeStart, start);
      const sliceEnd = Math.min(nodeEnd, stop);
      if (!(sliceStart < sliceEnd)) return null;
      let piece = '';
      let cursor = sliceStart;
      for (const position of softHyphens) {
        if (position <= sliceStart || position > sliceEnd) continue;
        piece += value.slice(cursor - nodeStart, position - nodeStart) + SOFT_HYPHEN;
        cursor = position;
      }
      piece += value.slice(cursor - nodeStart, sliceEnd - nodeStart);
      if (hyphen && !hyphenPlaced && stop <= nodeEnd) {
        piece += '-';
        hyphenPlaced = true;
      }
      return piece;
    }
    if (Array.isArray(node)) return node.map(slice);
    if (!React.isValidElement(node)) return null;

    const position = offset;
    if (typeof node.type === 'string' && BREAK_TAGS.has(node.type)) {
      const keep = (position > start || first) && (position < stop || last);
      if (!keep && position >= stop && !last) forcedEnd = true;
      return keep ? node : null;
    }
    const props = node.props ?? {};
    const sliced = slice(props.children);
    const nodeEnd = offset;
    if (nodeEnd === position) {
      // No text of its own (an empty span, a <wbr>): it belongs to exactly one piece.
      const keep = (start <= position && position < stop) || (last && position === stop);
      if (!keep) return null;
    } else if (nodeEnd <= start || position >= stop) {
      return null;
    }
    if (props.children === undefined) return node;
    return React.cloneElement(node, undefined, ...(Array.isArray(sliced) ? sliced : [sliced]));
  };

  const sliced = slice(children);
  return {
    children: Array.isArray(sliced) ? sliced : [sliced],
    justifyLast: !last && !forcedEnd,
    manualHyphens: hyphens.some((position) => position > from && position <= to),
  };
}
