// src/uhuu/editor-shell/document/option-core.js
// Pure, DOM-free values of an editor option, shared by page options (PageEditor's `pageOptions`,
// stored per page in `payload.pages[id]`) and document options (EditorShell.DocumentOptions, stored
// as top-level payload keys). One definition format, one way to read, match and type a value; only
// where the value is stored and where the control is drawn differ. option-controls.tsx draws them.
//
// A definition: { id, type?, label, description?, options?, min?, max?, step?, defaultValue?,
// field?, valueType? }. `field` is the stored key (default `id`); a document option written for
// uhuu-components 0.4 may still name it `key`.

const TYPES = new Set(['select', 'toggle', 'slider', 'counter', 'color-series']);

/** The control: `select` (the default), `toggle`, `slider`, `counter` or `color-series`. */
export function optionType(definition) {
  return TYPES.has(definition?.type) ? definition.type : 'select';
}

/** The key the value is stored under: `field`, else `id`, else the 0.4 document option `key`. */
export function optionField(definition) {
  return definition?.field ?? definition?.id ?? definition?.key;
}

/** The type a choice is written as: the declared one, else by control (toggle, slider/counter, text). */
export function optionValueType(definition) {
  const declared = definition?.valueType;
  if (declared === 'string' || declared === 'number' || declared === 'boolean') return declared;
  const type = optionType(definition);
  if (type === 'toggle') return 'boolean';
  if (type === 'slider' || type === 'counter') return 'number';
  return 'string';
}

function isRecord(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * The value a record holds for the option (`record[field]`), else the definition's default. A
 * `fallback` of true gives a control's empty value when there is neither: off, the minimum (or 0),
 * or "" (a page option select without a value is left out of its menu).
 */
export function readOptionValue(record, definition, { fallback = false } = {}) {
  const field = optionField(definition);
  const stored = isRecord(record) && field ? record[field] : undefined;
  const value = stored ?? definition?.defaultValue;
  if (value !== undefined || !fallback) return value;
  const type = optionType(definition);
  if (type === 'toggle') return false;
  if (type === 'slider' || type === 'counter') return typeof definition?.min === 'number' ? definition.min : 0;
  return '';
}

/**
 * Whether two values are the same choice. Compared as strings: the platform's dropdowns stored the
 * option's string, while templates often default to a number (`2` is `"2"`).
 */
export function sameOptionValue(a, b) {
  if (a === undefined || a === null || b === undefined || b === null) return false;
  return String(a) === String(b);
}

/** The choice a value matches, if any. */
export function findOptionChoice(definition, value) {
  const choices = Array.isArray(definition?.options) ? definition.options : [];
  return choices.find((choice) => sameOptionValue(choice?.value, value));
}

/** A toggle is on for `true` and `"true"`, the two forms a boolean takes in saved payloads. */
export function isOptionOn(value) {
  return value === true || value === 'true';
}

/** "" and whitespace are not numbers, although Number("") is 0. */
function asNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
  if (typeof value !== 'string' || value.trim() === '') return undefined;
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

/**
 * A choice typed as the option declares, ready to write: `number` converts (a value that is not a
 * number is kept as it is), `boolean` takes `true` / `"true"`, `string` stringifies.
 */
export function coerceOptionValue(definition, value) {
  if (value === undefined || value === null) return value;
  switch (optionValueType(definition)) {
    case 'number': {
      const number = asNumber(value);
      return number === undefined ? value : number;
    }
    case 'boolean':
      return isOptionOn(value);
    default:
      return String(value);
  }
}
