import { evaluatePageComponentKeys } from './page-items-core';
import { Plus, Search } from 'lucide-react';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from '../../ui/sheet';
import { AvailableItem, AvailableGroupItem, AvailablePageItem } from './use-page-groups';
import type { ReorderItem } from './page-group-utils';
import PageSizeUtils from '../../utility/PageSizeUtils';
import * as React from 'react';
import { useShellTranslation } from '../../i18n/locale-context';

interface AddPageDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  availableItems: AvailableItem[];
  onSelectItem: (item: AvailableItem) => Promise<void> | void;
  renderThumbnail?: (item: ReorderItem, index: number, isDragging?: boolean) => React.ReactNode;
  payload?: any;
  setup?: { width: number; height: number };
  gridColsClass?: string;
}

export function AddPageDialog({
  open,
  onOpenChange,
  availableItems,
  onSelectItem,
  renderThumbnail: defaultRenderThumbnail,
  payload,
  setup = { width: 210, height: 297 },
  gridColsClass = "uhuu-page-order-grid-cols",
}: AddPageDialogProps) {
  const shellI18n = useShellTranslation();
  const { t, localize } = shellI18n;
  const [searchQuery, setSearchQuery] = React.useState('');

  const filteredItems = React.useMemo(() => {
    if (!searchQuery.trim()) return availableItems;
    const q = searchQuery.toLowerCase();
    return availableItems.filter(item =>
      (localize(item.label) || '').toLowerCase().includes(q) ||
      item.id.toLowerCase().includes(q)
    );
  }, [availableItems, searchQuery, localize]);

  const handleSelect = (item: AvailableItem) => {
    onOpenChange(false);
    void onSelectItem(item);
  };

  const resolvedDimensions = PageSizeUtils.resolveDimensions(setup);
  const pageWidthMm = resolvedDimensions.width;
  const pageHeightMm = resolvedDimensions.height;
  const pageAspectRatio = pageWidthMm / pageHeightMm;
  const thumbnailWidth = 200;
  const thumbnailHeight = Math.round(thumbnailWidth / pageAspectRatio);
  const thumbnailStyle = {
    width: `${thumbnailWidth}px`,
    height: `${thumbnailHeight}px`,
  };

  const toReorderItem = (item: AvailableItem, index: number): ReorderItem => {
    if (item.kind === 'group') {
      const group = item as AvailableGroupItem;
      const context = { payload, item: undefined, parent: undefined };
      const componentKeys = evaluatePageComponentKeys(group.pageComponentKeys, context);
      const firstPageComponentKey = componentKeys[0];
      return {
        kind: 'group',
        id: item.id,
        label: item.label,
        pageCount: componentKeys.length,
        firstPageId: firstPageComponentKey,
        firstPageComponentKey,
      } as ReorderItem;
    }

    const pageItem = item as AvailablePageItem;
    const componentKey = pageItem.componentKey ?? pageItem.id;
    return {
      kind: 'page',
      id: pageItem.id,
      pageId: pageItem.id,
      pageComponentKey: componentKey,
      pageLabel: pageItem.label,
      pageNum: index + 1,
    } as ReorderItem;
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="uhuu:h-[90vh] uhuu:w-full uhuu:max-w-none uhuu:flex uhuu:flex-col uhuu:gap-0 uhuu:bg-gray-50 uhuu:p-0"
        data-uhuu-editor
      >
        <SheetHeader className="uhuu:border-b uhuu:border-gray-200 uhuu:p-4 uhuu:bg-(--uhuu-shell-surface)">
          <div className="uhuu:flex uhuu:items-end uhuu:gap-3">
            <div className="uhuu:w-8 uhuu:h-8 uhuu:bg-gray-100 uhuu:rounded-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:shrink-0 uhuu:mb-0.5">
              <Plus className="uhuu:w-4 uhuu:h-4" />
            </div>
            <div className="uhuu:flex-1">
              <SheetTitle className="uhuu:text-base uhuu:font-medium uhuu:text-gray-900 uhuu:leading-tight">
                {t('addDialog.title')}
              </SheetTitle>
              <SheetDescription className="uhuu:text-xs uhuu:text-gray-400 uhuu:mt-0.5">
                {t('addDialog.description')}
              </SheetDescription>
            </div>
            <div className="uhuu:mb-0.5 uhuu:mr-8 uhuu:flex uhuu:items-center uhuu:gap-1.5 uhuu:rounded-md uhuu:border uhuu:border-gray-200 uhuu:bg-(--uhuu-shell-surface) uhuu:px-2 uhuu:py-1 uhuu:text-gray-400 uhuu:focus-within:border-gray-400 uhuu:focus-within:ring-2 uhuu:focus-within:ring-gray-200">
              <Search className="uhuu:w-3.5 uhuu:h-3.5 uhuu:shrink-0" />
              <label className="uhuu:sr-only" htmlFor="uhuu-add-page-filter">{t('addDialog.filterLabel')}</label>
              <input
                id="uhuu-add-page-filter"
                type="text"
                placeholder={t('addDialog.filterPlaceholder')}
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                className="uhuu:w-24 uhuu:border-0 uhuu:bg-transparent uhuu:text-sm uhuu:text-gray-600 uhuu:placeholder:text-gray-400 uhuu:outline-none uhuu:transition-all uhuu:duration-150 uhuu:focus:w-40"
              />
            </div>
          </div>
        </SheetHeader>

        <div className="uhuu:min-h-0 uhuu:flex-1 uhuu:overflow-auto uhuu:bg-gray-50 uhuu:p-6">
          {filteredItems.length === 0 ? (
            <div className="uhuu:text-center uhuu:py-16">
              <div className="uhuu:w-16 uhuu:h-16 uhuu:bg-gray-100 uhuu:rounded-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:mx-auto uhuu:mb-4">
                <Plus className="uhuu:w-8 uhuu:h-8 uhuu:text-gray-400" />
              </div>
              <div className="uhuu:text-lg uhuu:font-medium uhuu:text-gray-900 uhuu:mb-2">{t('addDialog.emptyTitle')}</div>
              <p className="uhuu:text-gray-500 uhuu:mb-4">{searchQuery.trim() ? t('addDialog.emptyFiltered') : t('addDialog.emptyAdded')}</p>
            </div>
          ) : (
            <div className={gridColsClass}>
              {filteredItems.map((item, index) => {
                  const isGroup = item.kind === 'group';
                  const id = item.id;
                  const label = isGroup
                    ? (localize(item.label) || t('addDialog.groupFallbackName', { number: index + 1 }))
                    : (localize(item.label) || t('addDialog.pageFallbackName', { id: item.id }));
                  const context = { payload, item: undefined, parent: undefined };
                  const pageCount = isGroup 
                    ? evaluatePageComponentKeys((item as AvailableGroupItem).pageComponentKeys, context).length
                    : 1;
                  const hasDefaultThumbnail = !!defaultRenderThumbnail;
                  return (
                    <div
                      key={id}
                      onClick={() => handleSelect(item)}
                      onKeyDown={(event) => {
                        if (event.key === 'Enter' || event.key === ' ') {
                          event.preventDefault();
                          handleSelect(item);
                        }
                      }}
                      role="button"
                      tabIndex={0}
                      aria-label={t('addDialog.addItem', { name: label })}
                      className={[
                        "uhuu:group uhuu:relative uhuu:block uhuu:cursor-pointer uhuu:border-0 uhuu:bg-transparent uhuu:p-0 uhuu:text-left uhuu:transition-all uhuu:focus-visible:outline-none uhuu:focus-visible:ring-2 uhuu:focus-visible:ring-gray-900 uhuu:focus-visible:ring-offset-2",
                        !hasDefaultThumbnail && "uhuu:bg-(--uhuu-shell-surface) uhuu:border-2 uhuu:border-gray-200",
                      ].filter(Boolean).join(' ')}
                      style={thumbnailStyle}
                    >
                      {/* Thumbnail area */}
                      <div className="uhuu:w-full uhuu:h-full uhuu:relative">
                        {(item as any).thumbnail ? (
                          <div data-uhuu-paper className="uhuu:absolute uhuu:inset-0 uhuu:bg-gray-100 uhuu:hover:bg-white">
                            {/* The shell's frame around the template's picture: chrome on paper. */}
                            <img
                              data-uhuu-chrome
                              src={(item as any).thumbnail}
                              className="uhuu:w-full uhuu:h-full uhuu:object-contain uhuu:pointer-events-none uhuu:object-top uhuu:border uhuu:border-gray-200 uhuu:p-4"
                              alt={label}
                            />
                          </div>
                        ) : defaultRenderThumbnail ? (
                          <div className="uhuu:absolute uhuu:inset-0 uhuu:flex uhuu:items-center uhuu:pointer-events-none">
                            {defaultRenderThumbnail(toReorderItem(item, index), index, false)}
                          </div>
                        ) : (
                          <>
                            {isGroup ? (
                              <div className="uhuu:flex uhuu:h-full uhuu:flex-col uhuu:items-center uhuu:justify-center uhuu:p-4 uhuu:text-center">
                                <div className="uhuu:w-16 uhuu:h-16 uhuu:bg-blue-100 uhuu:rounded-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:mx-auto uhuu:mb-3">
                                  <Plus className="uhuu:w-8 uhuu:h-8 uhuu:text-blue-600" />
                                </div>
                                <div className="uhuu:text-sm uhuu:font-medium uhuu:text-gray-700">{label}</div>
                                <div className="uhuu:text-xs uhuu:text-gray-500 uhuu:mt-1">
                                  {t('page.count', { count: pageCount })}
                                </div>
                              </div>
                            ) : (
                              <div className="uhuu:flex uhuu:h-full uhuu:flex-col uhuu:items-center uhuu:justify-center uhuu:p-4 uhuu:text-center">
                                <div className="uhuu:w-16 uhuu:h-16 uhuu:bg-gray-100 uhuu:rounded-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:mx-auto uhuu:mb-3">
                                  <Plus className="uhuu:w-8 uhuu:h-8 uhuu:text-gray-400" />
                                </div>
                                <div className="uhuu:text-sm uhuu:font-medium uhuu:text-gray-700">{label}</div>
                                <div className="uhuu:text-xs uhuu:text-gray-500 uhuu:mt-1">{id}</div>
                              </div>
                            )}
                          </>
                        )}
                      </div>

                      {(!defaultRenderThumbnail || item?.thumbnail) && (
                        <>
                          {isGroup && (
                            <div className="uhuu:absolute uhuu:top-2 uhuu:right-2 uhuu:px-2 uhuu:py-1 uhuu:bg-blue-600/80 uhuu:backdrop-blur-sm uhuu:text-white uhuu:text-xs uhuu:font-medium uhuu:rounded uhuu:shadow-lg uhuu:pointer-events-none">
                              {t('thumbnail.groupBadge', { count: pageCount })}
                            </div>
                          )}

                          {/* Item info overlay - positioned at bottom to match reorder dialog */}
                          <div className="uhuu:absolute uhuu:bottom-0 uhuu:left-0 uhuu:right-0 uhuu:bg-(--uhuu-thumbnail-caption) uhuu:backdrop-blur-sm uhuu:p-3 uhuu:pointer-events-none" data-item-id={id}>
                            <div className="uhuu:flex uhuu:items-center uhuu:justify-between uhuu:gap-2 uhuu:text-white">
                              <div className="uhuu:flex-1 uhuu:min-w-0">
                                <div className="uhuu:text-sm uhuu:font-medium uhuu:truncate">{label}</div>                                
                              </div>                             
                            </div>
                          </div>
                        </>
                      )}

                      {/* Small hover indicator */}
                      <div className="uhuu:absolute uhuu:top-3 uhuu:left-3 uhuu:w-8 uhuu:h-8 uhuu:bg-black uhuu:rounded-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:shadow-lg uhuu:opacity-0 uhuu:group-hover:opacity-100 uhuu:transition-opacity uhuu:pointer-events-none uhuu:z-10">
                        <Plus className="uhuu:w-4 uhuu:h-4 uhuu:text-white" />
                      </div>
                    </div>
                  );
              })}
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}
