import { useEffect, useLayoutEffect, useRef } from 'react';
import { ASSET_WAIT_MS } from './flow-assets';
import { paginationReadiness } from './pagination-readiness';

const useIsoLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * Keeps `data-uhuu-pagination` at `measuring` while `pending` is true, for template work the
 * package cannot see (a map, a chart, data a page fetches), so a renderer does not print before
 * it is done. When it clears every flow is measured again. A hold lasts at most as long as a
 * pending image (10 s); then a console warning names `label` and the document stops waiting.
 * Held in a layout effect, so it is in place before the first commit can settle.
 */
export function usePaginationHold(pending = true, label?: string) {
  const labelRef = useRef(label);
  useIsoLayoutEffect(() => { labelRef.current = label; }, [label]);
  useIsoLayoutEffect(() => {
    if (!pending) return undefined;
    // A label names the work when it starts; changing its text must not extend the 10 s cap.
    const name = labelRef.current ? `usePaginationHold(${JSON.stringify(labelRef.current)})` : 'usePaginationHold()';
    return paginationReadiness.hold({ label: name, waitMs: ASSET_WAIT_MS });
  }, [pending]);
}
