import { useState, useRef, useEffect } from 'react';
import { ChevronDown, ArrowUp, ArrowDown, Plus, Copy, Trash2, Pencil } from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '../../ui/dropdown-menu';
import { useShellTranslation } from '../../i18n/locale-context';

export interface PageNameDropdownProps {
  name: string;
  canRename?: boolean;
  canMoveUp?: boolean;
  canMoveDown?: boolean;
  canAddPage?: boolean;
  canDuplicate?: boolean;
  canDelete?: boolean;
  onRename?: (name: string) => void;
  onMoveUp?: () => void;
  onMoveDown?: () => void;
  onAddPage?: () => void;
  onDuplicate?: () => void;
  onDelete?: () => void;
}

export function PageNameDropdown({
  name,
  canRename,
  canMoveUp,
  canMoveDown,
  canAddPage,
  canDuplicate,
  canDelete,
  onRename,
  onMoveUp,
  onMoveDown,
  onAddPage,
  onDuplicate,
  onDelete,
}: PageNameDropdownProps) {
  const { t } = useShellTranslation();
  const [open, setOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [renameValue, setRenameValue] = useState(name);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setRenameValue(name);
  }, [name]);

  useEffect(() => {
    if (isEditing) {
      setTimeout(() => {
        inputRef.current?.focus();
        inputRef.current?.select();
      }, 10);
    }
  }, [isEditing]);

  const commitRename = () => {
    const trimmed = renameValue.trim();
    if (trimmed && trimmed !== name) onRename?.(trimmed);
    setIsEditing(false);
  };

  const hasActions = canMoveUp || canMoveDown || canAddPage || canDuplicate || canDelete;
  const hasAnyContent = canRename || hasActions;

  if (isEditing) {
    return (
      <input
        ref={inputRef}
        value={renameValue}
        onChange={(e) => setRenameValue(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') commitRename();
          if (e.key === 'Escape') { setRenameValue(name); setIsEditing(false); }
          e.stopPropagation();
        }}
        onBlur={commitRename}
        className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-800 uhuu:bg-(--uhuu-shell-surface) uhuu:border uhuu:border-blue-400 uhuu:rounded-md uhuu:px-2 uhuu:py-1 uhuu:focus:outline-none uhuu:focus:ring-2 uhuu:focus:ring-blue-400/30 uhuu:max-w-[140px] uhuu:h-7"
        data-uhuu-editor
      />
    );
  }

  if (!hasAnyContent) {
    return (
      <span className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-600 uhuu:truncate uhuu:max-w-[120px]">
        {name}
      </span>
    );
  }

  return (
    <DropdownMenu open={open} onOpenChange={setOpen} modal={false}>
      <DropdownMenuTrigger asChild>
        <button
          className="uhuu:flex uhuu:items-center uhuu:gap-1 uhuu:text-xs uhuu:font-medium uhuu:text-gray-700 uhuu:hover:text-gray-900 uhuu:rounded-md uhuu:px-2 uhuu:h-7 uhuu:hover:bg-gray-100 uhuu:transition-colors uhuu:border uhuu:border-transparent uhuu:hover:border-gray-200"
          data-uhuu-editor
        >
          <span className="uhuu:truncate uhuu:max-w-[120px]">{name}</span>
          <ChevronDown className="uhuu:w-3.5 uhuu:h-3.5 uhuu:text-gray-500 uhuu:shrink-0" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="uhuu:min-w-44 uhuu:p-1" align="start">
        {canRename && (
          <DropdownMenuItem onSelect={(e) => { e.preventDefault(); setOpen(false); setIsEditing(true); }}>
            <Pencil className="uhuu:w-3.5 uhuu:h-3.5 uhuu:mr-2" />
            {t('page.rename')}
          </DropdownMenuItem>
        )}
        {canRename && hasActions && <DropdownMenuSeparator />}
        {canMoveUp && (
          <DropdownMenuItem onClick={onMoveUp}>
            <ArrowUp className="uhuu:w-3.5 uhuu:h-3.5 uhuu:mr-2" />
            {t('page.moveUp')}
          </DropdownMenuItem>
        )}
        {canMoveDown && (
          <DropdownMenuItem onClick={onMoveDown}>
            <ArrowDown className="uhuu:w-3.5 uhuu:h-3.5 uhuu:mr-2" />
            {t('page.moveDown')}
          </DropdownMenuItem>
        )}
        {canAddPage && (canMoveUp || canMoveDown) && <DropdownMenuSeparator />}
        {canAddPage && (
          <DropdownMenuItem onClick={onAddPage}>
            <Plus className="uhuu:w-3.5 uhuu:h-3.5 uhuu:mr-2" />
            {t('page.addPage')}
          </DropdownMenuItem>
        )}
        {canDuplicate && (
          <DropdownMenuItem onClick={onDuplicate}>
            <Copy className="uhuu:w-3.5 uhuu:h-3.5 uhuu:mr-2" />
            {t('page.duplicate')}
          </DropdownMenuItem>
        )}
        {canDelete && <DropdownMenuSeparator />}
        {canDelete && (
          <DropdownMenuItem onClick={onDelete} className="uhuu:text-red-600 uhuu:focus:text-red-700 uhuu:focus:bg-red-50">
            <Trash2 className="uhuu:w-3.5 uhuu:h-3.5 uhuu:mr-2" />
            {t('page.delete')}
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
