import * as React from "react"
import { createContext, useContext, useMemo, useState } from "react"
import { PortalRootProvider } from "./portal-root"
import { ToolbarSlotProvider } from "./toolbar-slot"
import { DiagnosticWarningsContext } from "../utility/diagnostics"
import {
  ShellLocaleProvider,
  useShellI18nRuntime,
  useShellTranslation,
  type ShellTranslations,
} from "../i18n/locale-context"
import { useShellAppearance } from "../appearance/appearance-runtime"
import type { ShellAppearance } from "../appearance/appearance-core.js"

interface InteractiveModeContextType {
  interactive: boolean
  setInteractive: (value: boolean) => void
  enableDevTools?: boolean
  /** The shell's chrome appearance; absent outside a provider (the hook falls back to the host's). */
  appearance?: ShellAppearance
}

const InteractiveModeContext = createContext<InteractiveModeContextType>({
  interactive: true,
  setInteractive: () => {},
  enableDevTools: false,
})

/**
 * Hook to access interactive mode state
 * Returns true if UI should show interactive elements (default), false to hide them.
 * `locale` is the shell's resolved interface language and `appearance` its chrome appearance
 * (`light` or `dark`), so template-owned chrome can follow both. Pages never follow `appearance`.
 */
export function useInteractive() {
  const context = useContext(InteractiveModeContext)
  const { locale } = useShellTranslation()
  const hostAppearance = useShellAppearance()
  const appearance = context.appearance ?? hostAppearance
  return useMemo(() => ({ ...context, locale, appearance }), [context, locale, appearance])
}

/**
 * Hook to check if UI elements should be hidden
 * Returns true when interactive mode is OFF
 */
export function useShouldHideUI(): boolean {
  const { interactive } = useInteractive()
  return !interactive
}

interface InteractiveModeProviderProps {
  children: React.ReactNode
  defaultInteractive?: boolean
  enableDevTools?: boolean
  /**
   * The shell's interface language (`de`, `fr`, `it`, `en`; region tags such as `de-CH` reduce
   * to the language). Without it the shell follows the host: uhuu-app's locale from the SDK
   * handshake, then `?lang=`, `<html lang>` and the browser. See docs/editor-shell-translations.md.
   */
  locale?: string
  /**
   * Per-language overrides of the shell's words, or a whole catalog for a language the package
   * does not ship (`{ de: { toolbar: { add: 'Neu' } }, rm: romanshCatalog }`). Pass a stable object.
   */
  translations?: ShellTranslations
  /**
   * Forces the shell chrome's appearance (`light` or `dark`). Without it the shell follows the
   * host: the uhuu document editor's handshake and live changes, then `?appearance=`, then light.
   * Pages are paper and never follow it. See docs/editor-shell-appearance.md.
   */
  appearance?: ShellAppearance
}

/** The PDF renderer sets `window.$uhuu_renderer`: the shell is never interactive there. */
export function isRendererMode() {
  return typeof window !== 'undefined' && Boolean((window as any)?.$uhuu_renderer)
}

function isHostEditorShellDevToolsEnabled() {
  if (typeof window === 'undefined') return false

  const hostConfig = (window as any)?.__uhuuPreviewHost
  return Boolean(hostConfig?.enableEditorShellDevTools)
}

/**
 * InteractiveModeProvider - Global control for showing/hiding UI elements
 * 
 * When interactive=true (default): Shows all controls (edit mode)
 * When interactive=false: Hides all UI elements (Print Mode)
 * 
 * @param defaultInteractive - Initial interactive mode state (default: true)
 * @param enableDevTools - Force enable dev tools (print mode controls) even in production (default: false)
 * @param locale - Shell interface language; defaults to the host's language, then detection
 * @param translations - Word overrides per language, or catalogs for additional languages
 * @param appearance - Shell chrome appearance; defaults to the host's, then `?appearance=`, then light
 * 
 * @example
 * ```tsx
 * <InteractiveModeProvider defaultInteractive={true} enableDevTools={true}>
 *   <MyApp />
 * </InteractiveModeProvider>
 * 
 * // Inside components:
 * const { interactive, setInteractive } = useInteractive()
 * <button onClick={() => setInteractive(!interactive)}>
 *   {interactive ? 'Hide UI' : 'Show UI'}
 * </button>
 * ```
 */
export function InteractiveModeProvider({
  children,
  defaultInteractive = true,
  enableDevTools = false,
  locale,
  translations,
  appearance,
}: InteractiveModeProviderProps) {
  const shouldDisableInteractive = isRendererMode()
  const effectiveEnableDevTools = enableDevTools || isHostEditorShellDevToolsEnabled()

  const effectiveDefaultInteractive = shouldDisableInteractive 
    ? false 
    : defaultInteractive
  
  const [interactive, setInteractive] = useState(effectiveDefaultInteractive)
  const shellI18n = useShellI18nRuntime({ locale, translations })
  const shellAppearance = useShellAppearance(appearance)
  const contextValue = useMemo(
    () => ({ interactive, setInteractive, enableDevTools: effectiveEnableDevTools, appearance: shellAppearance }),
    [interactive, effectiveEnableDevTools, shellAppearance]
  )

  return (
    <InteractiveModeContext.Provider value={contextValue}>
      <DiagnosticWarningsContext.Provider value={effectiveEnableDevTools}>
        <ShellLocaleProvider value={shellI18n}>
          <ToolbarSlotProvider>
            <PortalRootProvider>
              <div data-uhuu-interactive={interactive ? '' : undefined} style={{ display: 'contents' }}>
                {children}
              </div>
            </PortalRootProvider>
          </ToolbarSlotProvider>
        </ShellLocaleProvider>
      </DiagnosticWarningsContext.Provider>
    </InteractiveModeContext.Provider>
  )
}


